import { GRID_SIZES, isValidSize } from '../deck.ts';
import { MOVES_MAX } from '../game.ts';
import { isJsonObject, isNonnegativeSafeInteger, parseJson } from '../saved-format.ts';

export const DEFAULT_SIZE = GRID_SIZES[0];
export const PREFERENCES_KEY = 'neon-pairs.preferences.v1';
export const PREFERENCES_VERSION = 1;
export interface Preferences {
  readonly size: number;
  readonly bestMoves: Readonly<Record<string, number>>;
}
export interface PreferenceStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export function readPreferences(store: PreferenceStore | null): Preferences {
  const fallback: Preferences = { size: DEFAULT_SIZE, bestMoves: {} };
  try {
    const text = store?.getItem(PREFERENCES_KEY);
    if (!text) return fallback;
    const value = parseJson(text);
    if (
      !isJsonObject(value) ||
      value.schemaVersion !== PREFERENCES_VERSION ||
      typeof value.size !== 'number'
    )
      return fallback;
    if (!isValidSize(value.size) || !isJsonObject(value.bestMoves)) return fallback;
    const bestMoves: Record<string, number> = {};
    for (const [size, moves] of Object.entries(value.bestMoves)) {
      const numberSize = Number(size);
      if (
        String(numberSize) !== size ||
        !isValidSize(numberSize) ||
        !isNonnegativeSafeInteger(moves) ||
        moves > MOVES_MAX ||
        moves < numberSize ** 2 / 2
      )
        return fallback;
      bestMoves[size] = moves;
    }
    return { size: value.size, bestMoves };
  } catch {
    return fallback;
  }
}

export function writePreferences(store: PreferenceStore | null, preferences: Preferences): void {
  try {
    store?.setItem(
      PREFERENCES_KEY,
      JSON.stringify({ schemaVersion: PREFERENCES_VERSION, ...preferences }),
    );
  } catch {
    // A blocked browser store doesn't stop the current game.
  }
}

export function rememberBest(preferences: Preferences, size: number, moves: number): Preferences {
  return { ...preferences, bestMoves: { ...preferences.bestMoves, [size]: moves } };
}
import { useEffect } from 'react';
import { writePreferences } from './storage.ts';
import type { Preferences, PreferenceStore } from './storage.ts';

// Reading localStorage can throw when the browser blocks storage, and play continues without it.
export function browserStore(): PreferenceStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

// Saves this tab's size and bests after each change.
export function useSavedPreferences(store: PreferenceStore | null, preferences: Preferences) {
  useEffect(() => {
    writePreferences(store, preferences);
  }, [preferences, store]);
}
import { isWon } from '../game.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { StatusLabel } from './status-labels.ts';
import type { GameState } from '../game.ts';
import './status.css';

interface GameStatusProps {
  game: GameState;
  best: number | undefined;
  celebration: boolean;
}

export function GameStatus({ game, best, celebration }: GameStatusProps) {
  return (
    <>
      <dl className="stats">
        <div>
          <dt>{StatusLabel.moves}</dt> <dd>{game.moves}</dd>
        </div>
        <div>
          <dt>{StatusLabel.pairs}</dt>{' '}
          <dd>
            {game.matched.length / 2}/{game.deck.length / 2}
          </dd>
        </div>
        <div>
          <dt>{StatusLabel.time}</dt> <dd>{formatElapsed(game.elapsedMs)}</dd>
        </div>
        <div>
          <dt>{StatusLabel.best}</dt> <dd>{best ?? 0}</dd>
        </div>
      </dl>
      {isWon(game) && (
        <p className={`victory${celebration ? ' celebrate' : ''}`}>
          Every pair found in {game.moves} moves and {formatElapsed(game.elapsedMs)}. Well played.
        </p>
      )}
    </>
  );
}
import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

const MatchTone = 660;
const WinTone = 880;

function chime(frequency: number): void {
  const Context = window.AudioContext as typeof AudioContext | undefined;
  if (!Context) return;
  const audio = new Context();
  const tone = audio.createOscillator();
  const level = audio.createGain();
  tone.frequency.value = frequency;
  level.gain.value = 0.05;
  tone.connect(level).connect(audio.destination);
  tone.onended = () => void audio.close();
  tone.start();
  tone.stop(audio.currentTime + 0.12);
}

export function useGame() {
  const [store] = useState(browserStore);
  const [session, setSession] = useState(() => {
    const preferences = readPreferences(store);
    return initialSession(freshBoardCode(preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit);
  useSavedPreferences(store, session.preferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false));
  }

  function restart(): void {
    clock.reset();
    commit(replaceGame(current.current, createGame(current.current.game.boardCode), false));
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    const matched = current.current.game.matched.length;
    commit(activateSession(current.current, index));
    if (current.current.game.matched.length > matched) chime(current.current.celebration ? WinTone : MatchTone);
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return { session, newGame, restart, loadBoard, loadSnapshot, exportSnapshot, activate, resume };
}

import { useCallback, useRef, useState } from 'react';
import { useNearestScroll } from './nearest-scroll.ts';

const KEYBOARD_FOCUS = ':focus-visible';

// Keeps the board's remembered tab stop and scrolls keyboard focus into view with nearest
// alignment.
export function useBoardFocus() {
  const viewport = useRef<HTMLDivElement>(null);
  const element = useRef<HTMLDivElement>(null);
  const [focused, setFocused] = useState(0);
  const scrollToNearest = useNearestScroll(viewport);
  // Focus calls skip the browser's centering scroll and then scroll with nearest alignment.
  const focusRemembered = useCallback(() => {
    const card = element.current?.querySelectorAll('button').item(focused);
    card?.focus({ preventScroll: true });
    if (card) scrollToNearest(card);
  }, [focused, scrollToNearest]);
  const cardFocused = useCallback(
    (index: number, card: HTMLElement): void => {
      setFocused(index);
      // Moving a card under a pressed pointer would send the release elsewhere and lose the click.
      if (card.matches(KEYBOARD_FOCUS)) scrollToNearest(card);
    },
    [scrollToNearest],
  );
  return { viewport, element, focused, focusRemembered, cardFocused };
}
import { useCallback, useImperativeHandle, useLayoutEffect, useMemo, useRef } from 'react';
import { faceUpCards } from '../game.ts';
import { Card } from './Card.tsx';
import { useBoardFocus } from './use-board-focus.ts';
import type { CSSProperties, RefObject } from 'react';
import type { GameState } from '../game.ts';
import './board.css';

interface BoardProps {
  game: GameState;
  ref: RefObject<BoardFocus | null>;
  activate(index: number): void;
}
const NEAREST: ScrollIntoViewOptions = { block: 'nearest', inline: 'nearest' };
interface BoardStyle extends CSSProperties {
  '--grid-size': number;
}

export interface BoardFocus {
  focusRemembered(): void;
}

// Once a click or tap completes, the focused card can move fully into view.
function cardClicked(card: HTMLElement): void {
  card.scrollIntoView(NEAREST);
}

export function Board({ game, ref, activate }: BoardProps) {
  const { size, deck, matched, selection } = game;
  const { viewport, element, focused, focusRemembered, cardFocused } =
    useBoardFocus();
  useImperativeHandle(ref, () => ({ focusRemembered }), [focusRemembered]);
  // A clock tick keeps both arrays, so the cards' props stay equal and no card renders again.
  const faceUp = useMemo(() => faceUpCards({ matched, selection }), [matched, selection]);
  const matchedCards = useMemo(() => new Set(matched), [matched]);
  // The game passes a new handler on each render. Cards keep one callback that calls the latest.
  const latestActivate = useRef(activate);
  useLayoutEffect(() => {
    latestActivate.current = activate;
  });
  const activateCard = useCallback((index: number) => latestActivate.current(index), []);
  const style: BoardStyle = { '--grid-size': size };
  return (
    <div
      ref={viewport}
      className="board-viewport"
      role="region"
      aria-label="Game board"
      aria-describedby="board-help"
    >
      <div className="board" ref={element} style={style}>
        {deck.map((face, index) => (
          <Card
            key={index}
            index={index}
            size={size}
            face={faceUp.has(index) ? face : null}
            matched={matchedCards.has(index)}
            tabIndex={focused === index ? 0 : -1}
            activate={activateCard}
            focus={cardFocused}
            clicked={cardClicked}
          />
        ))}
      </div>
    </div>
  );
}
import { memo } from 'react';
import { Face } from './Face.tsx';
import { describeCard } from './card-state.ts';
import './card.css';

interface CardProps {
  index: number;
  size: number;
  face: number | null;
  matched: boolean;
  tabIndex: number;
  activate(index: number): void;
  focus(index: number, card: HTMLElement): void;
  clicked(card: HTMLElement): void;
}

// Memoized, so a clock tick that changes no card renders none of them.
export const Card = memo(function Card({
  index,
  size,
  face,
  matched,
  tabIndex,
  activate,
  focus,
  clicked,
}: CardProps) {
  const { state, label } = describeCard(index, size, face, matched);
  // Chromium sends no click after a context menu, a long press or a touch scroll, so every click
  // activates.
  return (
    <button
      type="button"
      className={`card ${state}`}
      aria-label={label}
      aria-disabled={matched}
      tabIndex={tabIndex}
      onFocus={(event) => focus(index, event.currentTarget)}
      onClick={(event) => {
        activate(index);
        clicked(event.currentTarget);
      }}
    >
      {face === null ? <span className="card-back" aria-hidden="true" /> : <Face face={face} />}
      {matched && (
        <svg className="matched-mark" viewBox="0 0 12 12" aria-hidden="true" focusable="false">
          <path d="m2 6 3 3 5-6" fill="none" stroke="currentColor" strokeWidth="2" />
        </svg>
      )}
    </button>
  );
});
