  assert.equal(arrowDestination(5, 4, 'ArrowUp'), 1);
  assert.equal(arrowDestination(5, 4, 'ArrowDown'), 9);
});

test('arrows stop at each edge without wrapping between rows', () => {
  assert.equal(arrowDestination(4, 4, 'ArrowLeft'), 4);
