  'block-size',
  'min-width',
  'min-height',
  'min-inline-size',
  'min-block-size',
  'grid-template-columns',
  'grid-template-rows',
  'perspective-origin',
  'transform-origin',
]);

function revealedCardStyle(page: Page) {
  return page
    .locator('.card.revealed')
    .first()
    .evaluate(
      async (card, placement) => {
