import { memo } from 'react';
import { Face } from './Face.tsx';
import { describeCard } from './card-state.ts';
import './card.css';

interface CardProps {
  index: number;
  size: number;
  face: number | null;
  matched: boolean;
  tabIndex: number;
  activate(index: number): void;
  focus(index: number, card: HTMLElement): void;
  clicked(card: HTMLElement): void;
}

// Memoized, so a clock tick that changes no card renders none of them.
export const Card = memo(function Card({
  index,
  size,
  face,
  matched,
  tabIndex,
  activate,
  focus,
  clicked,
}: CardProps) {
  const { state, label } = describeCard(index, size, face, matched);
  // Chromium sends no click after a context menu, a long press or a touch scroll, so every click
  // activates.
  return (
    <button
      type="button"
      className={`card ${state}`}
      aria-label={label}
      aria-disabled={matched}
      tabIndex={tabIndex}
      onFocus={(event) => focus(index, event.currentTarget)}
      onClick={(event) => {
        activate(index);
        clicked(event.currentTarget);
      }}
    >
      {face === null ? <span className="card-back" aria-hidden="true" /> : <Face face={face} />}
      {matched && (
        <svg className="matched-mark" viewBox="0 0 12 12" aria-hidden="true" focusable="false">
          <path d="m2 6 3 3 5-6" fill="none" stroke="currentColor" strokeWidth="2" />
        </svg>
      )}
    </button>
  );
});
.card {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  padding: 0;
  scroll-margin: 6px;
  border: 2px solid var(--border);
  border-radius: 8px;
  background: var(--back);
  color: var(--text);
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
  transition: border-color 120ms ease;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.card:hover {
  border-color: var(--text);
}
.card.revealed,
.card.matched {
  background: var(--face);
}
.card.matched {
  border-color: var(--green);
}
.card > svg {
  display: block;
  width: 100%;
  height: 100%;
}
.card-back {
  width: 12px;
  height: 12px;
  border: 2px solid var(--secondary);
  transform: rotate(45deg);
}
/* A corner mark wider than about 17% of the card would reach the top-right marker. */
.card > .matched-mark {
  position: absolute;
  right: 0;
  top: 0;
  width: 16%;
  height: 16%;
  color: var(--green);
}
.stats {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 24px;
  margin: 0 0 16px;
}
.stats div {
  min-width: 8ch;
}
dt,
dd {
  display: inline;
}
dt {
  color: var(--secondary);
  font-size: 14px;
}
dd {
  margin: 0;
  font-variant-numeric: tabular-nums;
}
.victory {
  padding: 12px 16px;
  margin-bottom: 12px;
  color: var(--text);
  border: 1px solid var(--border);
  border-radius: 8px;
}
.celebrate {
  animation: victory-pulse 600ms ease-out 1;
}
@keyframes victory-pulse {
  50% {
    background: var(--panel);
    opacity: 0.75;
  }
}

